import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Two to four options of the same thing (Night / Day, 7d / 30d). One is always on.
 * The selection slides to the new option instead of jumping, so the eye follows the change.
 */
export interface SegmentedOption<T extends string> {
  value: T
  label: string
  disabled?: boolean
}

export interface SegmentedControlProps<T extends string> {
  options: SegmentedOption<T>[]
  value: T
  onChange: (value: T) => void
  /** Read out by screen readers, e.g. "Theme". */
  label?: string
  className?: string
}

export function SegmentedControl<T extends string>({ options, value, onChange, label, className }: SegmentedControlProps<T>) {
  const refs = React.useRef<Record<string, HTMLButtonElement | null>>({})
  const [box, setBox] = React.useState<{ x: number; w: number } | null>(null)
  const first = React.useRef(true)

  React.useLayoutEffect(() => {
    const place = () => {
      const el = refs.current[value]
      if (el) setBox({ x: el.offsetLeft, w: el.offsetWidth })
    }
    place()
    window.addEventListener("resize", place)
    return () => window.removeEventListener("resize", place)
  }, [value, options])

  React.useEffect(() => {
    first.current = false
  }, [])

  return (
    <div data-slot="segmented" role="group" aria-label={label} className={cn("relative isolate inline-flex p-0.5 shadow-[inset_0_0_0_1px_var(--border)]", className)}>
      {box && (
        <span
          aria-hidden="true"
          className={cn("absolute inset-y-0.5 left-0 -z-10 bg-[var(--gc-sel-bg)] motion-safe:transition-[transform,width] motion-safe:duration-300 motion-safe:ease-gc", first.current && "transition-none")}
          style={{ width: box.w, transform: `translateX(${box.x}px)` }}
        />
      )}
      {options.map((o) => (
        <button
          key={o.value}
          ref={(el) => {
            refs.current[o.value] = el
          }}
          type="button"
          aria-pressed={o.value === value}
          disabled={o.disabled}
          onClick={() => onChange(o.value)}
          className={cn(
            "h-7 px-3 text-[13px] text-muted-foreground outline-none transition-colors duration-200 ease-gc hover:text-foreground",
            "focus-visible:outline-[1.5px] focus-visible:-outline-offset-2 focus-visible:outline-foreground",
            "aria-pressed:text-[var(--gc-sel-fg)] aria-pressed:hover:text-[var(--gc-sel-fg)]",
            "disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:text-muted-foreground"
          )}
        >
          {o.label}
        </button>
      ))}
    </div>
  )
}
